const currentShift = $('Iterate Shifts').item.json;
const policies = $('Fetch Operating Policy').all().map(item => item.json);

// Extract dynamic business hours
let opStart = "05:00";
let opEnd = "22:00";
policies.forEach(p => {
  if (p['Policy Name'] === 'Operating_Day_Start') opStart = p.Value;
  if (p['Policy Name'] === 'Operating_Day_End') opEnd = p.Value;
});

// Calculate true required duration dynamically
const startDt = new Date(currentShift['Scheduled Start Time']);
const endDt = new Date(currentShift['Scheduled End Time']);
const durationHours = Math.abs(endDt - startDt) / 36e5;

// Use the Audit Queue for dynamic de-confliction (ignoring the current job)
const allShifts = $('Fetch Pending Shifts').all().map(item => item.json);
const otherScheduledTasks = allShifts
  .filter(shift => shift['Job ID'] !== currentShift['Job ID'] && shift.Status !== 'Cancelled')
  .map(shift => {
    return {
      job_id: shift['Job ID'],
      location: shift['Location Name'],
      start_time: shift['Scheduled Start Time'].includes('T') ? shift['Scheduled Start Time'].split('T')[1].substring(0, 5) : "08:00",
      end_time: shift['Scheduled End Time'] && shift['Scheduled End Time'].includes('T') ? shift['Scheduled End Time'].split('T')[1].substring(0, 5) : "16:00"
    };
  });

// Extract FortyGuard API Temps
const features = $json.data.result.map_data.features || [];
let totalTempC = 0;
features.forEach(f => { totalTempC += f.properties.average_temperature || 28; });
let avgTempF = Math.round(((features.length > 0 ? totalTempC / features.length : 28) * 9/5) + 32);

// Build thermal timeline
let environmental_timeline = [];
for (let hour = parseInt(opStart.split(':')[0]); hour <= parseInt(opEnd.split(':')[0]); hour++) {
  let heatDelta = (hour >= 12 && hour <= 16) ? 14 : (hour >= 10 && hour <= 18) ? 8 : 0;
  let tempF = avgTempF + heatDelta;
  let risk = (tempF >= 100) ? "HIGH" : (tempF >= 91) ? "CAUTION" : "SAFE";
  environmental_timeline.push({ time: `${hour.toString().padStart(2, '0')}:00`, temp_f: tempF, risk_level: risk });
}

return {
  schedulingContext: {
    current_job: {
      job_id: currentShift['Job ID'],
      location: currentShift['Location Name'],
      scheduled_start: currentShift['Scheduled Start Time'].includes('T') ? currentShift['Scheduled Start Time'].split('T')[1].substring(0, 5) : "08:00",
      duration_hours: durationHours
    },
    business_operating_bounds: { earliest_start: opStart, latest_finish: opEnd },
    company_active_schedule: otherScheduledTasks,
    environmental_timeline: environmental_timeline
  }
};

const item = $input.item.json;

// 1. Read dynamically from output, text, or the object directly
let rawText = item.output || item.text || item.message?.content || (typeof item === 'string' ? item : null);
let parsed = null;

if (typeof item.output === 'object' && item.output !== null) {
  parsed = item.output;
} else if (rawText) {
  try {
    const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (err) {
    return {
      json: {
        job_id: $('Iterate Shifts').item.json['Job ID'] || "UNKNOWN",
        status: "HUMAN_INTERVENTION_REQUIRED",
        agent_action: `🚨 PARSING ERROR: Could not parse AI response.\n• Error: ${err.message}\n• Raw Text: ${rawText}`
      }
    };
  }
} else if (typeof item === 'object') {
  parsed = item;
}

if (!parsed) {
  return {
    json: {
      job_id: $('Iterate Shifts').item.json['Job ID'] || "UNKNOWN",
      status: "HUMAN_INTERVENTION_REQUIRED",
      agent_action: "🚨 SYSTEM ERROR: No data received from AI engine."
    }
  };
}

// 2. Extract dynamic fields produced by the model
const decision = (parsed.decision || parsed.status || "").toUpperCase().trim();
const reason = parsed.reason || "";
const newStart = parsed.new_start || "";
const newEnd = parsed.new_end || "";

// 3. Extract dynamic OSHA mandates array returned by the model
let mandatesText = "";
if (Array.isArray(parsed.osha_mandates) && parsed.osha_mandates.length > 0) {
  mandatesText = "\n\n🛡️ OSHA Mandates:\n" + parsed.osha_mandates.map(m => `• ${m}`).join("\n");
}

let finalStatus = "";
let agentActionText = "";

// 4. Pure dynamic assignment based on the model's actual decision
if (decision === "SAFE") {
  finalStatus = "SAFE";
  agentActionText = `✅ SAFE (Approved as scheduled)\n• Reason: ${reason}${mandatesText}`;
} else if (decision.includes("RESCHEDULE")) {
  finalStatus = "RESCHEDULED";
  agentActionText = `⚠️ RESCHEDULED: Operational boundary or heat risk detected.\n• Reason: ${reason}\n• Proposed Window: ${newStart} - ${newEnd}${mandatesText}`;
} else {
  finalStatus = "HUMAN_INTERVENTION_REQUIRED";
  agentActionText = `🚨 ESCALATED: Requires Human Review.\n• Decision Code: ${decision}\n• Reason: ${reason}${mandatesText}`;
}

const activeJobId = parsed.job_id || $('Iterate Shifts').item.json['Job ID'] || "UNKNOWN";

return {
  json: {
    job_id: activeJobId,
    status: finalStatus,
    agent_action: agentActionText
  }
};

// Grab original link as fallback
let originalUrl = $('Iterate Shifts').item.json['Google Maps Link'];
let expandedUrl = originalUrl;

// Intercept redirect location from HTTP response headers
if ($json.headers && $json.headers.location) {
    expandedUrl = $json.headers.location;
}

// Robust regex matching both direct coords, query parameters, and comma formats
const regex = /@(-?\d+\.\d+),(-?\d+\.\d+)|[?&]q=(-?\d+\.\d+)(?:%2C|,)(-?\d+\.\d+)/;
const match = expandedUrl.match(regex);

if (!match) {
  throw new Error("Could not automatically extract coordinates from this Google Maps link: " + expandedUrl);
}

return {
  lat: parseFloat(match[1] || match[3]),
  lon: parseFloat(match[2] || match[4])
};

const shifts = $input.all().map(item => item.json);

let escalatedCount = 0;
let safeCount = 0;
let tableRows = '';

shifts.forEach(shift => {
  if (!shift['Job ID']) return; 

  const status = shift['Status'] || 'UNKNOWN';
  let statusColor = status.includes('SAFE') ? '#10b981' : (status.includes('RESCHEDULED') ? '#f59e0b' : '#ef4444');

  if (status.includes('SAFE')) safeCount++;
  else escalatedCount++;

  // Clean and format the AI's detailed reasoning
  let rawAction = shift['Agent Action'] || 'No additional details provided.';
  let agentAction = rawAction.replace(/\n/g, '<br>');

  tableRows += `
    <tr>
      <td style="padding: 12px; border-bottom: 1px solid #e5e7eb; vertical-align: top;"><strong>${shift['Job ID']}</strong></td>
      <td style="padding: 12px; border-bottom: 1px solid #e5e7eb; vertical-align: top;">${shift['Location Name']}</td>
      <td style="padding: 12px; border-bottom: 1px solid #e5e7eb; vertical-align: top;">
        <span style="color: ${statusColor}; font-weight: bold; font-size: 14px;">${status}</span>
        <div style="margin-top: 8px; font-size: 13px; color: #4b5563; background-color: #f9fafb; padding: 10px; border-radius: 6px; border-left: 4px solid ${statusColor};">
          ${agentAction}
        </div>
      </td>
    </tr>
  `;
});

const emailHTML = `
  <div style="font-family: Arial, sans-serif; max-width: 650px; margin: 0 auto; color: #1f2937;">
    <h2 style="color: #2563eb; border-bottom: 2px solid #2563eb; padding-bottom: 10px;">ThermaShift AI - Daily Dispatch Summary</h2>
    <p><strong>Prepared for Dispatcher:</strong> Shahrukh Karim</p>
    <p>The autonomous scheduling engine has completed the daily thermal audit. Below is the executive summary of all active shifts.</p>

    <div style="background-color: #f3f4f6; padding: 15px; border-radius: 8px; margin-bottom: 20px;">
      <h3 style="margin-top: 0; color: #111827;">System Overview:</h3>
      <ul style="margin-bottom: 0;">
        <li><strong>Total Shifts Analyzed:</strong> ${shifts.length}</li>
        <li><strong>✅ Cleared for Safe Operations:</strong> ${safeCount}</li>
        <li><strong>🚨 Flagged for Review (Escalated/Rescheduled):</strong> ${escalatedCount}</li>
      </ul>
    </div>

    <table style="width: 100%; border-collapse: collapse; text-align: left;">
      <thead>
        <tr style="background-color: #f8fafc;">
          <th style="padding: 10px 12px; border-bottom: 2px solid #cbd5e1; width: 15%;">Job ID</th>
          <th style="padding: 10px 12px; border-bottom: 2px solid #cbd5e1; width: 30%;">Location</th>
          <th style="padding: 10px 12px; border-bottom: 2px solid #cbd5e1; width: 55%;">AI Decision & Actions</th>
        </tr>
      </thead>
      <tbody>
        ${tableRows}
      </tbody>
    </table>

    <p style="font-size: 12px; color: #6b7280; margin-top: 30px; border-top: 1px solid #e5e7eb; padding-top: 10px;">
      Automated message generated by ThermaShift AI Engine. Do not reply.
    </p>
  </div>
`;

return [{ json: { html_body: emailHTML, subject: `🚨 ThermaShift Dispatch Summary (${safeCount} Safe, ${escalatedCount} Flagged)` } }];
